    const L0 = IDS.filter(x => S.fam === 'all' || FAM(x) === S.fam), L = L0.indexOf(id) >= 0 ? L0 : IDS, k = L.indexOf(id);
    inner.appendChild(top(t('ih_title'), [btn(t('ih_shelf'), '', shelf)], [arrowBtn(t('ih_prev'), he() ? 'r' : 'l', false, () => page(L[(k - 1 + L.length) % L.length])), arrowBtn(t('ih_next'), he() ? 'l' : 'r', true, () => page(L[(k + 1) % L.length]))]));
