      const span = lv >= 2 && innerWidth >= 760 ? 24 : 12;
      const win = { lo: Math.max(R.lo - (((R.lo % 12) + 12) % 12), Math.round(((R.lo + R.hi) / 2 - span / 2) / 12) * 12) };
