    const recB = el('button', 'ih-btn ih-recBtn'); recB.type = 'button'; recB.appendChild(el('i')); const recL = el('span', null, t('ih_rec')); recB.appendChild(recL);
    const listenB = btn(t('ih_listen'), '', () => listen()), againB = btn(t('ih_again'), '', () => start()), keepB = btn(t('ih_keep'), 'gold', () => keep()), songB = btn(t('ih_toSong'), 'line', () => song(S.lastSample));
    [listenB, againB, keepB].forEach(b => { b.disabled = true; }); songB.style.display = 'none';
    recB.onclick = () => start(); [recB, listenB, againB, keepB, songB].forEach(b => row.appendChild(b));
    const along = el('label', 'ih-along'); const alongC = el('input'); alongC.type = 'checkbox'; alongC.checked = S.along !== false; alongC.onchange = () => { S.along = alongC.checked; }; along.appendChild(alongC); along.appendChild(document.createTextNode(t('ih_playAlong'))); row.appendChild(along); rc.appendChild(row);
    const roll = el('div', 'ih-roll'); for (let b = 0; b <= 8; b++) { const g = el('i', 'bt' + (b % 4 ? '' : ' bar')); g.style.left = (b / 8 * 100) + '%'; roll.appendChild(g); } const ph = el('i', 'ph'); roll.appendChild(ph); rc.appendChild(roll);
    const hint = el('p', 'ih-hint', t('ih_recHint')); rc.appendChild(hint); d.appendChild(rc);
    const BPM = 100, SPB = 60 / BPM, BEATS = 8, Q = lv === 3 ? 0.25 : 0.5;
    let take = [];
    const lo = R ? R.lo : 0, hi = R ? R.hi : 1;
    const yOf = (m, k) => k ? 8 + PADS.indexOf(k) * 12 : 72 - ((m - lo) / Math.max(1, hi - lo)) * 62;
    function drawTake() { roll.querySelectorAll('.nt').forEach(n => n.remove()); take.forEach(ev => { const n = el('i', 'nt'); n.style.left = (ev.b / BEATS * 100) + '%'; n.style.width = Math.max(1.2, (ev.d || Q) / BEATS * 100) + '%'; n.style.top = yOf(ev.m, ev.kind) + 'px'; n.style.background = ev.kind ? '#e2bf68' : M.HUE[((ev.m % 12) + 12) % 12]; roll.appendChild(n); }); }
    function click(acc) { const c = M.ac(); if (!c) return; const o = c.createOscillator(), g = c.createGain(), t0 = c.currentTime; o.frequency.value = acc ? 1600 : 1100; g.gain.setValueAtTime(0.0001, t0); g.gain.exponentialRampToValueAtTime(0.16, t0 + 0.004); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.06); o.connect(g); g.connect(c.destination); o.start(t0); o.stop(t0 + 0.08); }
