      take = []; drawTake(); [listenB, againB, keepB].forEach(b => { b.disabled = true; }); songB.style.display = 'none'; recB.classList.add('live'); recL.textContent = t('ih_count'); hint.textContent = t('ih_recHint');
      const cnt = el('div', 'cnt'); roll.appendChild(cnt); let beat = -4; const c = M.ac(); rec = { t0: null, on: {} }; const me = rec;
