  /* the same sung tune by the man, an octave lower (his range is G2–B♭3): swapped in from the lane's Woman / Man switch */
  const EXTRA = [{ id: 'rk_voice', role: 'voice', inst: 'voice', key: 'ih_p_voiceM', cap: 'ih_c_voice', ev: N([[52, 0, 2], [50, 2, 1], [48, 3, 1], [45, 4, 3], [48, 7, 1]], 1, 0.85) }];
  /* a part is playable only if its instrument is (the voice waits for its recordings) */
  const ready = p => p.inst === 'drums' || !!(window.KQ_MUSIC_SPRITES || {})[p.inst];
  Object.values(KITS).forEach(k => { k.parts = k.parts.filter(ready); });
  const PARTS = [].concat(...Object.values(KITS).map(k => k.parts), EXTRA.filter(ready));
  const VOICE_TWIN = { rk_voice_f: 'rk_voice', rk_voice: 'rk_voice_f' };
  const smpName = s => s.key ? t(s.key) : t('ih_smp', { i: nameOf(s.inst), n: s.n || '' });
