          const ctl = el('div', 'ws-blkctl'); const mk = (txt, lab, fn) => { const x = el('button', 'ih-mini', txt); x.type = 'button'; x.setAttribute('aria-label', lab); x.title = lab; x.onclick = fn; ctl.appendChild(x); };
