    const smp = { [id + 'b']: { inst: 'drums', ev: seg.beat }, [id + 'l']: { inst: bassInst(), ev: seg.bass }, [id + 'r']: { inst: W.riff.inst, ev: seg.riff, key: 'ws_blk_riff' }, [id + 'q']: { inst: W.riff.inst, ev: seg.riffSoft },
      [id + 'c']: { inst: W.chorus.inst, ev: seg.chorus, key: 'ws_blk_chorus' }, [id + 'v']: { inst: W.verse.inst, ev: seg.verse, key: 'ws_blk_verse' }, [id + 'h']: { inst: W.chorus.inst, ev: seg.harm.map(e => Object.assign({}, e, { vel: 0.5 })) } };
